const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const C = JSON.parse(await fs.readFile(S+"\\_GIG_CLEAN_FINAL.json","utf8"));

// 修正：cards=0 的降级为「A-」
const WEAK = ["fiverr.com","preply.com","bugbase.in"];
const fixed = {total:0, groups:{}, excluded:C.excluded};
for (const [cat, items] of Object.entries(C.groups)) {
  fixed.groups[cat] = items.map(it=>{
    const h = String(it.host).toLowerCase().replace(/^www\./,"");
    if (WEAK.includes(h)) return {...it, group:"仅见价格", tier:"A-"};
    return {...it, tier: it.group==="能看到活" ? "A" : "B"};
  });
  fixed.total += fixed.groups[cat].length;
}
await fs.writeFile(S+"\\_GIG_FINAL_V2.json", JSON.stringify(fixed,null,1), "utf8");

// 重新统计
const all = Object.values(fixed.groups).flat();
const tiers = {};
for (const a of all) tiers[a.tier]=(tiers[a.tier]||0)+1;
return { total: fixed.total, tiers };
